-- Invite codes let people join private rooms. 10 hex chars from a random
-- UUID; regenerated by owners/moderators when a code leaks.
ALTER TABLE rooms
    ADD COLUMN invite_code text NOT NULL UNIQUE
        DEFAULT substr(replace(gen_random_uuid()::text, '-', ''), 1, 10);

-- What the user is studying during a session (optional, short).
ALTER TABLE study_sessions
    ADD COLUMN topic text NOT NULL DEFAULT '' CHECK (char_length(topic) <= 100);

-- Stats queries scan a user's finished sessions by start time.
CREATE INDEX study_sessions_user_ended_idx ON study_sessions (user_id, started_at)
    WHERE ended_at IS NOT NULL;
